import pyomo.environ as pyo

# ----------------------------------------------------------------------
# DATA: every numeric constant lives here
# ----------------------------------------------------------------------
DATA = {
    "num_jobs": 7,          # 7 jobs
    "ops_per_job": 2,       # 2 operations per job
    "proc_time": 1,         # each operation takes 1 unit of time
    "big_M": 1000,          # big-M for disjunctive constraints
    # Machine assignment: job j has op 1 on machine M1 and op 2 on machine M2.
    # (j, o) -> machine index
    "machine": {
        (j, o): (0 if o == 1 else 1)
        for j in range(1, 8)
        for o in range(1, 3)
    },
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel(name="job_shop_makespan")

    # ---------------- Sets ----------------
    model.J = pyo.RangeSet(1, d["num_jobs"])
    model.O = pyo.RangeSet(1, d["ops_per_job"])

    op_list = [
        (j, o)
        for j in range(1, d["num_jobs"] + 1)
        for o in range(1, d["ops_per_job"] + 1)
    ]
    model.OP = pyo.Set(initialize=op_list, dimen=2)

    # ---------------- Conflict pairs (share same machine) ----------------
    machine = d["machine"]
    pair_list = []
    for ia in range(len(op_list)):
        for ib in range(ia + 1, len(op_list)):
            a = op_list[ia]
            b = op_list[ib]
            if machine[a] == machine[b]:
                pair_list.append((a[0], a[1], b[0], b[1]))

    if pair_list:
        model.PAIRS = pyo.Set(initialize=pair_list, dimen=4)
    else:
        model.PAIRS = pyo.Set(initialize=[(0, 0, 0, 0)], dimen=4)
        model.PAIRS_empty = pyo.Set(initialize=[])

    # ---------------- Variables ----------------
    model.s = pyo.Var(model.OP, within=pyo.NonNegativeReals)
    model.Cmax = pyo.Var(within=pyo.NonNegativeReals)

    if pair_list:
        model.y = pyo.Var(model.PAIRS, within=pyo.Binary)

    # ---------------- (1) Precedence within a job ----------------
    def precedence_rule(m, j, o):
        if o < d["ops_per_job"]:
            return m.s[j, o + 1] >= m.s[j, o] + d["proc_time"]
        return pyo.Constraint.Skip

    model.precedence = pyo.Constraint(model.J, model.O, rule=precedence_rule)

    # ---------------- (2) Disjunctive constraints on shared machines ----
    if pair_list:
        def disjunctive_ab_rule(m, a1, a2, b1, b2):
            M = d["big_M"]
            p = d["proc_time"]
            return m.s[b1, b2] - m.s[a1, a2] >= p - M * (1 - m.y[a1, a2, b1, b2])

        def disjunctive_ba_rule(m, a1, a2, b1, b2):
            M = d["big_M"]
            p = d["proc_time"]
            return m.s[a1, a2] - m.s[b1, b2] >= p - M * m.y[a1, a2, b1, b2]

        model.disjunctive_ab = pyo.Constraint(
            model.PAIRS, rule=disjunctive_ab_rule
        )
        model.disjunctive_ba = pyo.Constraint(
            model.PAIRS, rule=disjunctive_ba_rule
        )

    # ---------------- (3) Makespan >= every completion time -------------
    def makespan_rule(m, j, o):
        return m.Cmax >= m.s[j, o] + d["proc_time"]

    model.makespan_link = pyo.Constraint(model.OP, rule=makespan_rule)

    # ---------------- Objective ----------------
    model.obj = pyo.Objective(expr=model.Cmax, sense=pyo.minimize)

    return model


